vec3 col1 = vec3(.7, .4, .1);
vec3 col2 = vec3(.3, .4, .4);
vec3 col3 = vec3(.4, .1, .8);

vec4 getColor(vec2 uv) {
    vec3 color = col1 + (col2-col1) * uv.x;
    color += (col3-color) * (1.-uv.y)*(.8+.2*uv.x);

    return vec4(color, 1.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    vec2 t = vec2(
        (uv.x-.5) * iResolution.x/iResolution.y + .5,
        uv.y);

    if (t.x < 0. || t.x >= 1.) fragColor = vec4(0., 0., 0., 1.);
    else fragColor = getColor(t);
}
